  'Xodimning hisobi, JSHSHIRi va davomati bitta bo‘lib qoladi. Faqat yangi lavozimi qo‘shiladi.':
    'Учётная запись, ПИНФЛ и табель сотрудника остаются едиными. Добавляется только новая должность.',
