  'Xodim o‘z filialida qoladi va bu filialga kelishilgan soat hajmida ishlab beradi. Ish kunlari belgilanmaydi, haqiqiy soat turniket yozuvlaridan hisoblanadi.':
    'Сотрудник остаётся в своём филиале и отрабатывает для этого филиала согласованный объём часов. Рабочие дни не назначаются, фактические часы считаются по записям турникета.',
