  'Uch xizmat: ish joyidan ma’lumotnoma, tavsifnoma va lavozimga nomzodlik arizasi. Birinchi ikkitasi xodimlar uchun, uchinchisi «Mehmon» roli uchun.': 'Три услуги: справка с места работы, характеристика и заявка на рассмотрение кандидатуры на должность. Первые две — для сотрудников, третья — для роли «Гость».',
