  'Oylik davr yo‘q — avval «KPI sozlamalari»da davr yarating': 'Нет месячного периода — сначала создайте период в «Настройках КПЭ»',
  'Oy tugagach: rag‘bat va jarimalarni jadvalga kiriting, holatni tekshiring va oyni bitta tugma bilan yoping — yozuvlar yakunlanadi, varaqalar hisoblanadi, QR kodli hisobot tasdiqlanadi.': 'После окончания месяца: внесите поощрения и взыскания в таблицу, проверьте состояние и закройте месяц одной кнопкой — записи завершаются, листы пересчитываются, отчёт с QR-кодом утверждается.',
