  'Baholash varaqalari yaratilmagan — hisobot yozuvlar bo‘yicha tuziladi': 'Листы оценки не созданы — отчёт строится по записям',
  'Davr bir oydan uzun — yakunlanadi, lekin oylik hisobot tuzilmaydi': 'Период длиннее месяца — он будет закрыт, но месячный отчёт не создаётся',
  'Oy yopilgan: hisobot tasdiqlangan': 'Месяц закрыт: отчёт утверждён',
  'Hisobotni darhol o‘z nomimdan tasdiqlash': 'Сразу утвердить отчёт от своего имени',
  'Oyni yopish': 'Закрыть месяц',
  'Barcha yozuvlar yakunlanadi, varaqalar qayta hisoblanib muzlatiladi va oy uchun QR kodli KPI hisoboti yaratiladi. Yakunlangan yozuvni faqat bosh administrator o‘zgartira oladi.': 'Все записи будут завершены, листы пересчитаны и заморожены, и будет создан отчёт КПЭ за месяц с QR-кодом. Завершённую запись может изменить только главный администратор.',
  'Oy yopildi: {{locked}} ta yozuv yakunlandi, {{sheets}} ta varaqa hisoblandi': 'Месяц закрыт: завершено записей — {{locked}}, пересчитано листов — {{sheets}}',
