  'Yozuvlar va varaqalar «Jarayonda» holatiga qaytadi, tasdiqlangan hisobot «bekor qilingan» deb belgilanadi — o‘chirilmaydi, QR tekshiruvida bekor qilingani ko‘rinadi. Tuzatib, oyni qayta yopganingizda yangi hisobot yaratiladi.': 'Записи и листы вернутся в статус «В процессе», утверждённый отчёт будет помечен как отменённый — он не удаляется, и проверка по QR покажет, что он отменён. После исправлений и повторного закрытия месяца будет создан новый отчёт.',
