  'Faqat JPG, PNG yoki WEBP rasm yuklang': 'Загрузите изображение JPG, PNG или WEBP',
  'Bu rol har bir xodimda avtomatik bor — a’zo qo‘shish shart emas. Bu yerda faqat xodimga ochiq ruxsatlar belgilanadi; qo‘shimcha huquq kerak bo‘lsa, xodimni boshqa rolga qo‘shing.': 'Эта роль есть у каждого сотрудника автоматически — добавлять участников не нужно. Здесь задаются права, открытые сотруднику; для дополнительных прав добавьте сотрудника в другую роль.',
  'Qo‘l ostida xodimi bor har kim bu rolga avtomatik kiradi. Bu yerga faqat qo‘shimcha kishilarni qo‘shing.': 'Каждый, у кого есть подчинённые, входит в эту роль автоматически. Добавляйте сюда только дополнительных людей.',
  'Ko‘p filialli roli «Kadr» bo‘lgan xodimlar avtomatik kiradi. Bu yerga faqat qo‘shimcha kishilarni qo‘shing.': 'Сотрудники с многофилиальной ролью «Кадры» входят автоматически. Добавляйте сюда только дополнительных людей.',
  'Administrator hisoblari avtomatik kiradi. Bu yerga faqat qo‘shimcha kishilarni qo‘shing.': 'Учётные записи администраторов входят автоматически. Добавляйте сюда только дополнительных людей.',
  'KPI administratori belgisi bor xodimlar avtomatik kiradi. Bu yerga faqat qo‘shimcha kishilarni qo‘shing.': 'Сотрудники с отметкой «Администратор KPI» входят автоматически. Добавляйте сюда только дополнительных людей.',
  'Yana ko‘rsatish': 'Показать ещё',
  'Xodim va administrator hisoblari, rol vakillari va kiosklar': 'Учётные записи сотрудников и администраторов, представители ролей и киоски',
  'Tizim administratori — foydalanuvchilar, ma’lumotnomalar va ro‘yxatdan o‘tish arizalari.': 'Системный администратор — пользователи, справочники и заявки на регистрацию.',
  '«Administratorlar» tabida hisob oching: elektron pochta, parol va filial.': 'Во вкладке «Администраторы» создайте учётную запись: e-mail, пароль и филиал.',
