  'Barcha xodimlarga har ish kuni avtomatik to‘liq kun (8 soat) qo‘yilsin': 'Всем сотрудникам автоматически ставить полный день (8 часов) в каждый рабочий день',
  'Yoqilsa, filialning umumiy tabelida (tabel sahifasi, Excel, tabel hisobotlari) har bir xodimning har ish kuni turniketdan qat’i nazar «Keldi» va kunlik norma bilan chiqadi (to‘liq stavkada 8 soat, yarim stavkada o‘z grafigi). Ta’til, kasallik, xizmat safari va buyruq kunlari o‘z belgisida qoladi, dam olish va bayram kunlari — dam. Xodimning shaxsiy tabelida esa doim FAKT (turniket bo‘yicha) ko‘rinadi.': 'Если включено, в общем табеле филиала (страница табеля, Excel, отчёты-табели) каждый рабочий день каждого сотрудника показывается как «Пришёл» с дневной нормой независимо от турникета (8 часов на полной ставке, на неполной — по своему графику). Дни отпуска, болезни, командировки и приказов сохраняют свою отметку, выходные и праздники — выходной. В личном табеле сотрудника всегда отображается ФАКТ (по турникету).',
