  'Xodim boshqa yozuvlarda ishlatilgan — uni o‘chirish o‘rniga arxivga o‘tkazing': 'Сотрудник используется в других записях — вместо удаления переведите его в архив',
  'JSHSHIR 14 ta raqamdan iborat bo‘lishi kerak': 'ПИНФЛ должен состоять из 14 цифр',
