  'Boshlang‘ich parol': 'Начальный пароль',
  'Kamida 8 belgi, harf va raqam aralash; login bo‘lmasin. Foydalanuvchi birinchi kirishda uni almashtiradi.': 'Не менее 8 символов, буквы и цифры; без логина. Пользователь сменит его при первом входе.',
  'Xodim rolidagi hisob uchun kadrlar hisobida (T-2) karta ham ochiladi — bo‘lim va lavozimni keyin kadrlar bo‘limi to‘ldiradi. Ma’lumoti bo‘lmagan karta hisob o‘chirilganda u bilan birga o‘chadi.': 'Для учётной записи с ролью сотрудника также открывается кадровая карточка (Т-2) — отдел и должность затем заполняет отдел кадров. Карточка без данных удаляется вместе с учётной записью.',
