  'Shaxsiy daraja belgilansa, u rol darajasi o‘rnini bosadi — oshiradi yoki pasaytiradi. O‘zingizdagidan yuqori huquq berib bo‘lmaydi.': 'Личный уровень заменяет уровень роли — повышает или понижает его. Нельзя выдать права выше собственных.',
