  '«{{name}}» tizimga kira olmaydi, faol sessiyalari yopiladi.': '«{{name}}» не сможет войти в систему, активные сессии будут закрыты.',
  '«{{name}}» hisobi o‘chiriladi va uning barcha sessiyalari yopiladi.': 'Учётная запись «{{name}}» будет удалена, все её сессии будут закрыты.',
