  'Arxivlash mumkin emas — avval quyidagilarni yakunlang': 'Архивирование невозможно — сначала завершите следующее',
  'Yozuv o‘chirilmaydi, arxivga olinadi: xodimning tizimga kirishi to‘xtatiladi, bog‘liq hujjatlar tarixi saqlanadi. Kerak bo‘lsa xodimni keyinroq qayta ishga qabul qilish mumkin.': 'Запись не удаляется, а переносится в архив: вход сотрудника в систему прекращается, история связанных документов сохраняется. При необходимости сотрудника можно позже принять на работу повторно.',
