  'Parol kamida {{n}} ta belgidan iborat bo‘lishi kerak': 'Пароль должен содержать не менее {{n}} символов',
  'Parol o‘rnatildi. Xodimga yetkazing.': 'Пароль установлен. Сообщите его сотруднику.',
  'Parol emailga yuborilmaydi — uni o‘zingiz yetkazing. Bu vaqtinchalik parol: xodim kirganda uni almashtiradi. Xodimning faol sessiyalari yopiladi, navbatdagi avtomatik parol xati bekor qilinadi.': 'Пароль не отправляется по e-mail — сообщите его сами. Это временный пароль: сотрудник сменит его при входе. Активные сеансы сотрудника закрываются, ожидающее автоматическое письмо с паролем отменяется.',
