  // ── hrExt: tahrir to‘qnashuvi, arxivdan tiklash, xodimlarni o‘tkazish, bog‘liqliklar, hisobot shakllari ──
  'Ma’lumot boshqa foydalanuvchi tomonidan o‘zgartirildi': 'Данные изменены другим пользователем',
  '{{name}} bu yozuvni {{at}} da o‘zgartirdi.': '{{name}} изменил(а) эту запись {{at}}.',
  'Boshqa foydalanuvchi bu yozuvni {{at}} da o‘zgartirdi.': 'Другой пользователь изменил эту запись {{at}}.',
  '«Yangisini yuklash» oxirgi saqlangan ma’lumotlarni ochadi — siz kiritgan o‘zgarishlar bekor bo‘ladi. Ularni nusxalab olish uchun «Bekor qilish» ni bosing: forma ochiq qoladi, so‘ng ma’lumotlarni yangilang.': '«Загрузить новые» откроет последние сохранённые данные — ваши изменения будут отменены. Чтобы скопировать их, нажмите «Отмена»: форма останется открытой, затем обновите данные.',
  'Yangisini yuklash': 'Загрузить новые',
  'Oxirgi saqlangan ma’lumotlar yuklandi — o‘zgarishlaringizni qayta kiriting': 'Загружены последние сохранённые данные — внесите изменения заново',
  'Arxivdan tiklash': 'Восстановить из архива',
  'Xodim arxivga o‘tkazilishidan oldingi bo‘lim va lavozimiga qaytariladi, hisob va shaxsiy ma’lumotlari tiklanadi. Amal xodim tarixiga yoziladi.': 'Сотрудник возвращается в подразделение и на должность, которые занимал до архивации; учётная запись и личные данные восстанавливаются. Действие записывается в историю сотрудника.',
