  '«{{name}}» bo‘limini o‘chirib bo‘lmaydi: unda {{count}} ta faol va {{archived}} ta arxivdagi xodim bor. Ularni boshqa bo‘limga o‘tkazing — so‘ng o‘chirish qayta bajariladi.': 'Подразделение «{{name}}» нельзя удалить: в нём {{count}} действующих и {{archived}} архивных сотрудников. Переведите их в другое подразделение — затем удаление будет выполнено повторно.',
